export class TrackingPage {
  private http = inject(HttpClient);

  readonly tableKey = 'tracking.component';

  /** sections (T6-11): one table visible at a time */
  trackTab = signal<string>('custodies');
  readonly tabs: AppTab[] = [
    { id: 'custodies', label: 'custody.tracking.custodies' },
    { id: 'agents', label: 'custody.tracking.by_agent' },
  ];

  readonly agentColumns = [
    { field: 'agent', searchField: 'agent.name', header: 'custody.tracking.col_agent', sortable: false },
    { field: 'count', header: 'custody.tracking.count', sortable: false },
    { field: 'total_amount', header: 'common.amount', sortable: false },
    { field: 'transferred_in', header: 'custody.list.col_transferred_in', sortable: false },
    { field: 'spent', header: 'custody.tracking.spent', sortable: false },
    { field: 'returned', header: 'custody.tracking.returned', sortable: false },
    { field: 'remaining', header: 'custody.tracking.remaining', sortable: false },
  ];

  readonly custodyColumns = [
    { field: 'id', header: 'custody.return_requests.col_number', sortable: false },
    { field: 'agent', header: 'custody.tracking.col_agent', sortable: false },
    { field: 'created_at', header: 'common.date', sortable: false },
    { field: 'amount', header: 'common.amount', sortable: false },
    { field: 'transferred_in', header: 'custody.list.col_transferred_in', sortable: false },
    { field: 'transferred_out', header: 'custody.list.col_transferred_out', sortable: false },
    { field: 'spent', header: 'custody.tracking.spent', sortable: false },
    { field: 'returned', header: 'custody.tracking.returned', sortable: false },
    { field: 'remaining', header: 'custody.tracking.remaining', sortable: false },
    { field: 'status', header: 'common.status', sortable: false },
    { field: 'actions', header: 'common.actions', sortable: false },
  ];

  readonly movementCols = [
    { field: 'date', header: 'common.date' },
    { field: 'type', header: 'common.type' },
    { field: 'description', header: 'common.description' },
    { field: 'user', header: 'custody.movements.col_by' },
    { field: 'amount', header: 'common.amount', numeric: true },
  ];

  /** the same status list all-custodies.blade.php filters on */
  readonly statusValues = [
    'all', 'pending', 'accepted', 'active', 'rejected', 'partially_returned', 'closed',
  ];

  /** one full dataset — the paginator is a single page */
  readonly perPage = 1000;



  data = resource<TrackingResponse, unknown>({
    loader: () =>
      firstValueFrom(this.http.get<TrackingResponse>('/custodies/tracking')),
  });

  private translate = inject(TranslateService);

  private label(key: string): string {
    const text = this.translate.instant(key);
    if (text === key) {
      warnMissingTranslation(key); // dev only — the raw key in the UI means a key was lost (T5-01)
    }
    return text !== key ? text : key;
  }

  statusOptions = computed(() =>
    this.statusValues.map((value) => ({
      label: value === 'all' ? this.label('custody.list.tab_all') : this.label(`enums.custody_status.${value}`),
      value,
    })),
  );

  /** agent options built from the payload itself — custody rows carry agent names, not ids */
  agentOptions = computed(() => {
    const names = [...new Set((this.data.value()?.data.custodies ?? [])
      .map((c) => c.agent)
      .filter((name): name is string => name !== null))].sort();
    return [
      { label: this.label('custody.tracking.all_agents'), value: 'all' },
      ...names.map((name) => ({ label: name, value: name })),
    ];
  });

  /** status + agent filters are client-side — the endpoint takes no params */
  /** the table's static filter engine filters these rows (T6-30) */
  allCustodies = computed(() => this.data.value()?.data.custodies ?? []);

  /** T6-30: agent + status as JSON defs — the table draws and runs them */
  readonly trackingFilters: TableFilterDef[] = [
    { key: 'agent', label: 'custody.tracking.col_agent', type: 'select', optionsFrom: 'rows', order: 1 },
    { key: 'status', label: 'common.status', type: 'select', optionsFrom: 'rows', order: 2 },
  ];

  movementsOpen = signal(false);
  movementsLoading = signal(false);
  movements = signal<CustodyMovements | null>(null);

  summaryValue(key: string): string {
    return this.data.value()?.data.stats[key] ?? '0';
  }

  /** per-custody row actions: open the detail or the movements dialog (all-custodies.blade.php) */
  custodyActions(row: TrackingCustody): RowActionItem[] {
    return [
      { icon: 'eye', label: 'common.view', route: ['/custodies', row.id] },
      { icon: 'history', label: 'custody.tracking.view_movements', handler: () => { this.openMovements(row.id); } },
    ];
  }

  openMovements(custodyId: number): void {
    this.movementsOpen.set(true);
    this.movementsLoading.set(true);
    this.movements.set(null);
    void firstValueFrom(this.http.get<ItemResponse<CustodyMovements>>(`/custodies/${custodyId}`))
      .then((res) => {
        this.movementsLoading.set(false);
        this.movements.set(res.data);
      })
      .catch(() => {
        this.movementsLoading.set(false);
        this.movements.set(null);
      });
  }
}
